FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 106: std's query functions no batch had evaluated. Generated by tools/fixtures/gen-batch-106.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function mm(p is Vector) returns array
{
    return [roundToPrecision(p[0] / millimeter, 6), roundToPrecision(p[1] / millimeter, 6), roundToPrecision(p[2] / millimeter, 6)];
}

// How many bodies, faces, edges and vertices a query finds.
function counts(context is Context, q is Query) returns map
{
    return { "bodies" : size(evaluateQuery(context, qEntityFilter(q, EntityType.BODY))), "faces" : size(evaluateQuery(context, qEntityFilter(q, EntityType.FACE))),
             "edges" : size(evaluateQuery(context, qEntityFilter(q, EntityType.EDGE))), "vertices" : size(evaluateQuery(context, qEntityFilter(q, EntityType.VERTEX))) };
}

// Everything a case made, of every kind.
function everythingOf(id is Id) returns Query
{
    const bodies = qCreatedBy(id, EntityType.BODY);
    return qUnion([bodies, qOwnedByBody(bodies, EntityType.FACE), qOwnedByBody(bodies, EntityType.EDGE), qOwnedByBody(bodies, EntityType.VERTEX)]);
}

// The points of the vertices a query finds, sorted.
function vertexPoints(context is Context, q is Query) returns array
{
    return sort(mapArray(evaluateQuery(context, q), function(v) { return mm(evVertexPoint(context, { "vertex" : v })); }),
        function(a, b) { return a[0] != b[0] ? a[0] - b[0] : (a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]); });
}

// unique: two blocks side by side, sharing a face's corners: their vertices, and the unique ones (which block keeps the shared ones)
export function c001(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const bSketch = newSketchOnPlane(context, id + "bSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(bSketch, "rect1", { "firstCorner" : vector(10, 0) * millimeter, "secondCorner" : vector(20, 10) * millimeter });
    skSolve(bSketch);
    extrude(context, id + "b", { "entities" : qSketchRegion(id + "bSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const all = qOwnedByBody(qUnion([qCreatedBy(id + "a", EntityType.BODY), qCreatedBy(id + "b", EntityType.BODY)]), EntityType.VERTEX);
    const unique = qUniqueVertices(all);
    return { "all" : size(evaluateQuery(context, all)), "unique" : size(evaluateQuery(context, unique)), "fromA" : size(evaluateQuery(context, qIntersection([unique, qOwnedByBody(qUnion([qCreatedBy(id + "a", EntityType.BODY)]), EntityType.VERTEX)]))), "points" : vertexPoints(context, unique) };
}

// tolerance: a block's and a filleted block's edges and vertices past tolerances of 0, 1e-9 m and 1e-5 m
export function c002(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const bSketch = newSketchOnPlane(context, id + "bSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(bSketch, "rect1", { "firstCorner" : vector(20, 0) * millimeter, "secondCorner" : vector(30, 10) * millimeter });
    skSolve(bSketch);
    extrude(context, id + "b", { "entities" : qSketchRegion(id + "bSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qCreatedBy(id + "b", EntityType.BODY), EntityType.EDGE), vector(25, 0, 10) * millimeter), "radius" : 3 * millimeter });
    const both = qUnion([qOwnedByBody(qCreatedBy(id + "a", EntityType.BODY), EntityType.EDGE), qOwnedByBody(qCreatedBy(id + "a", EntityType.BODY), EntityType.VERTEX), qOwnedByBody(qCreatedBy(id + "b", EntityType.BODY), EntityType.EDGE), qOwnedByBody(qCreatedBy(id + "b", EntityType.BODY), EntityType.VERTEX)]);
    return { "zero" : counts(context, qToleranceFilter(both, 0 * meter)), "nano" : counts(context, qToleranceFilter(both, 1e-9 * meter)), "big" : counts(context, qToleranceFilter(both, 1e-5 * meter)) };
}

// line: a block (10 mm) and the entities touching lines: through its middle along x, along an edge's line, through a corner diagonally, and missing it
export function c003(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const all = everythingOf(id + "a");
    return { "middle" : counts(context, qIntersectsLine(all, line(vector(5, 5, 5) * millimeter, vector(1, 0, 0)))), "edgeLine" : counts(context, qIntersectsLine(all, line(vector(0, 0, 50) * millimeter, vector(0, 0, 1)))), "corner" : counts(context, qIntersectsLine(all, line(vector(10, 10, 10) * millimeter, normalize(vector(1, -1, 2))))), "miss" : counts(context, qIntersectsLine(all, line(vector(0, 20, 0) * millimeter, vector(1, 0, 0)))) };
}

// ball: a block (10 mm) and the entities within radii of points: 1 mm of a corner, 2 mm of a face's middle, 0 mm of an edge's middle, 1 mm of a point 0.5 mm off a face
export function c004(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const all = everythingOf(id + "a");
    return { "corner" : counts(context, qWithinRadius(all, vector(10, 10, 10) * millimeter, 1 * millimeter)), "face" : counts(context, qWithinRadius(all, vector(5, 5, 10) * millimeter, 2 * millimeter)), "edge" : counts(context, qWithinRadius(all, vector(5, 0, 0) * millimeter, 0 * millimeter)), "near" : counts(context, qWithinRadius(all, vector(5, 5, 10.5) * millimeter, 1 * millimeter)) };
}

// coedge: a coedge of a block's top and one of its edges, evaluated
export function c005(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const top = qContainsPoint(qOwnedByBody(qCreatedBy(id + "a", EntityType.BODY), EntityType.FACE), vector(5, 5, 10) * millimeter);
    const edge = qContainsPoint(qOwnedByBody(qCreatedBy(id + "a", EntityType.BODY), EntityType.EDGE), vector(5, 0, 10) * millimeter);
    try { return { "count" : size(evaluateQuery(context, qCoEdge(top, edge))) }; } catch (error) { return { "error" : error }; }
}

// mesh: a mesh's source of a block's vertex (no meshes)
export function c006(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    try { return { "bodies" : size(evaluateQuery(context, qSourceMesh(qOwnedByBody(qCreatedBy(id + "a", EntityType.BODY), EntityType.VERTEX), EntityType.BODY))), "faces" : size(evaluateQuery(context, qSourceMesh(qOwnedByBody(qCreatedBy(id + "a", EntityType.BODY), EntityType.VERTEX), EntityType.FACE))) }; } catch (error) { return { "error" : error }; }
}

// axis: a cylinder about z (radius 5) beside a block: the faces and edges about z, about the cylinder's axis reversed, about x, and lines along a block's edge
export function c007(context is Context, id is Id)
{
    const cylSketch = newSketchOnPlane(context, id + "cylSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(cylSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(cylSketch);
    extrude(context, id + "cyl", { "entities" : qSketchRegion(id + "cylSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(10, 0) * millimeter, "secondCorner" : vector(20, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const all = qUnion([everythingOf(id + "cyl"), everythingOf(id + "a")]);
    return { "z" : counts(context, qAxis(all, line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)))), "down" : counts(context, qAxis(all, line(vector(0, 0, 7) * millimeter, vector(0, 0, -1)))), "x" : counts(context, qAxis(all, line(vector(0, 0, 0) * millimeter, vector(1, 0, 0)))), "blockEdge" : counts(context, qAxis(all, line(vector(10, 0, 3) * millimeter, vector(0, 0, 1)))) };
}
